"d-flex justify-content-between fs-5 mt-3"><strong>Total</strong><strong id="total">0.00</strong></div><div class="mt-2"><label class="form-label">Paid Amount</label><input name="paid" id="paid" type="number" step="0.01" min="0" value="0" class="form-control" required></div><div class="mt-2"><label class="form-label">Payment Method</label><select name="payment_method" class="form-select"><option value="cash">Cash</option><option value="easypaisa">Easypaisa</option><option value="jazzcash">JazzCash</option><option value="bank">Bank</option><option value="credit">Credit / Udhaar</option></select></div><button class="btn btn-success w-100 mt-3" id="completeSale">Complete Sale</button></div></div></div></form>@endsection
@push('scripts')<script>
const cart=new Map();const fmt=n=>Number(n||0).toFixed(2);
document.querySelectorAll('.add-product').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.id;const old=cart.get(id);cart.set(id,{id,name:b.dataset.name,unit:b.dataset.unit,price:Number(b.dataset.price),qty:old?old.qty+1:1});render();}));
document.getElementById('searchProduct').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#productRows tr').forEach(r=>r.hidden=!r.dataset.name.includes(q));});
document.getElementById('discount').addEventListener('input',render);
function render(){let html='',sub=0;for(const [id,i] of cart){const line=i.qty*i.price;sub+=line;html+=`<div class="border-bottom py-2"><div class="d-flex justify-content-between"><strong>${i.name}</strong><button type="button" class="btn btn-sm text-danger" onclick="removeItem('${id}')">×</button></div><div class="d-flex gap-2 mt-1"><input aria-label="Quantity" type="number" min="0.001" step="0.001" value="${i.qty}" class="form-control form-control-sm" style="width:90px" onchange="setQty('${id}',this.value)"><span class="small align-self-center">${i.unit} × Rs.${fmt(i.price)}</span><strong class="ms-auto">${fmt(line)}</strong></div><input type="hidden" name="items[${id}][product_id]" value="${id}"><input type="hidden" name="items[${id}][quantity]" value="${i.qty}"><input type="hidden" name="items[${id}][unit_price]" value="${i.price}"></div>`;}document.getElementById('cart').innerHTML=html||'<p class="text-muted">Add products to bill.</p>';const total=Math.max(0,sub-Number(document.getElementById('discount').value||0));document.getElementById('subtotal').textContent=fmt(sub);document.getElementById('total').textContent=fmt(total);document.getElementById('paid').value=fmt(total);}
function setQty(id,v){const x=cart.get(id);x.qty=Math.max(.001,Number(v));render()}function removeItem(id){cart.delete(id);render()}
document.getElementById('posForm').addEventListener('submit',e=>{if(!cart.size){e.preventDefault();alert('Please add at least one product.')}});render();
</script>@endpush
